cat > scripts/align.mjs <<'EOF'
#!/usr/bin/env node
// Writes public/narration/<slug>.vtt: one cue per sentence of the article,
// timed against your recording by forced alignment (stable-ts / Whisper).
//
//   node scripts/align.mjs <slug>            # reads public/audio/<slug>.mp3
//   node scripts/align.mjs <slug> --dry-run  # just print the sentences
//
// Needs `uv` (brew install uv) and ffmpeg. First run downloads a Whisper model.
import { execFileSync } from "node:child_process";
import { mkdtempSync, readFileSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

// ponytail: regex markdown stripping, not a real parser. A sentence it gets
// wrong just isn't highlighted (the page matches cues by text). Swap in
// remark if articles start using heavy MDX.
export function sentences(mdx) {
  const text = mdx
    .replace(/^---\n[\s\S]*?\n---\n/, "") // frontmatter
    .replace(/^```[\s\S]*?^```/gm, "") // code fences
    .replace(/^(import|export) .*$/gm, "")
    .replace(/<[^>]+>/g, "") // JSX / HTML tags
    .replace(/!\[[^\]]*\]\([^)]*\)/g, "") // images
    .replace(/\[([^\]]*)\]\([^)]*\)/g, "$1") // links -> their text
    .replace(/^\s*(#{1,6}|>|[-*+]|\d+\.)\s+/gm, "\n") // block markers start a new block
    .replace(/[*_`~]/g, "")
    .replace(/([^\n])\n(?!\n)/g, "$1 "); // hard-wrapped lines are one paragraph
  const segmenter = new Intl.Segmenter("en", { granularity: "sentence" });
  return text
    .split(/\n+/)
    .flatMap((block) => [...segmenter.segment(block)].map((s) => s.segment.trim()))
    .filter((s) => /[\p{L}\p{N}]/u.test(s));
}

function selfCheck() {
  const got = sentences(
    "---\ntitle: x\n---\n\n## A heading\n\nFirst *one*. Second,\nwrapped [link](http://x).\n\n- item\n\n```js\ncode. here.\n```\n",
  );
  const want = ["A heading", "First one.", "Second, wrapped link.", "item"];
  if (JSON.stringify(got) !== JSON.stringify(want)) throw new Error(`sentences() self-check failed: ${JSON.stringify(got)}`);
}

if (import.meta.filename === process.argv[1]) {
  selfCheck();
  const [slug, flag] = process.argv.slice(2);
  if (!slug) {
    console.error("usage: node scripts/align.mjs <slug> [--dry-run]");
    process.exit(1);
  }
  const lines = sentences(readFileSync(`src/content/articles/${slug}.mdx`, "utf8"));
  if (flag === "--dry-run") {
    console.log(lines.join("\n"));
    process.exit(0);
  }
  const textFile = join(mkdtempSync(join(tmpdir(), "align-")), "text.txt");
  writeFileSync(textFile, lines.join("\n"));
  const out = `public/narration/${slug}.vtt`;
  execFileSync(
    "uvx",
    ["--from", "stable-ts", "stable-ts", `public/audio/${slug}.mp3`, "--align", textFile, "--language", "en",
      "--original_split", "true", "--word_level", "false", "--overwrite", "-o", out],
    { stdio: "inherit" },
  );
  const cues = (readFileSync(out, "utf8").match(/-->/g) ?? []).length;
  if (cues !== lines.length) {
    console.error(`\n${out}: ${cues} cues for ${lines.length} sentences. Check the file; sentences without a matching cue won't be highlighted.`);
    process.exit(1);
  }
  console.log(`\n${out}: ${cues} cues. Upload the audio:\n  pnpm wrangler r2 object put site-audio/${slug}.mp3 --file public/audio/${slug}.mp3 --remote`);
}
EOF
